const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

// Best-time gate: publish inside IST peak windows (07:00-09:00, 19:00-22:00)
// unless payload body.forcePublish === true. Mirrors
// src/lib/publishing/best-time.ts (slots 07:30, 08:30, 19:30, 20:30 IST).
const item = $input.first().json;
const body = item.body ?? {};
const forced = body.forcePublish === true;
const istNow = new Date(Date.now() + (5 * 60 + 30) * 60000);
const mins = istNow.getUTCHours() * 60 + istNow.getUTCMinutes();
const peak = (mins >= 420 && mins < 540) || (mins >= 1140 && mins < 1320);
const slots = [450, 510, 1170, 1230];
const next = slots.find((s) => s > mins);
const fmt = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0') + ' IST';
const nextSlotIst = next === undefined ? '07:30 IST (tomorrow)' : fmt(next);
return [{ json: { ...item, bestTime: { peakNow: peak || forced, forced, nextSlotIst } } }];

return [{ json: { product: { state: 'DEFERRED' },
  reason: 'outside_peak_window',
  nextSlotIst: $json.bestTime ? $json.bestTime.nextSlotIst : null,
  note: 'Publish at the next IST peak slot (07:30 / 08:30 / 19:30 / 20:30), or re-trigger with forcePublish=true' } }];

const j = $input.first().json;
const ok = Boolean(j.id);
return [{ json: { pageOk: ok, pageId: j.id ?? null, pageName: j.name ?? null } }];

const wh = $('webhook-entry').first().json; const p = (wh.body ?? wh).product ?? {};
const fbId = $('fb-reel-start').first().json.video_id;
return [{ json: { product: { ...p, state: 'PUBLISHED',
  publications: { ...(p.publications ?? {}),
    facebook: { mediaId: fbId, publishedAt: new Date().toISOString() } } } } }];
